import base64, gzip, json
from pathlib import Path

DATA_B64 = ''''''

categories=json.loads(gzip.decompress(base64.b64decode(DATA_B64)).decode('utf-8'))
codes={'राजनीतिक':'POL','सामाजिक':'SOC','सांस्कृतिक':'CUL','आर्थिक':'ECO','वैज्ञानिक':'SCI','खेलकुद':'SPT','पुस्तक':'BOK','पुरस्कार':'AWD','कला':'ART','साहित्य':'LIT','संगीत':'MUS','अन्य_महत्त्वपूर्ण':'OTH'}
sources={'राजनीतिक':'राष्ट्रपतिको कार्यालय/प्रधानमन्त्री तथा मन्त्रिपरिषद्को कार्यालय/संयुक्त राष्ट्रसंघ/Reuters','सामाजिक':'WHO Nepal/UNESCO','सांस्कृतिक':'UNESCO/UNESCO World Heritage Centre','आर्थिक':'नेपाल अर्थ मन्त्रालय/Reuters/World Bank','वैज्ञानिक':'NASA/Reuters/Nature','खेलकुद':'FIFA/US Open/Wimbledon','पुस्तक':'The Booker Prizes','पुरस्कार':'Oscars/Recording Academy','कला':'Oscars/UNESCO','साहित्य':'The Booker Prizes','संगीत':'Recording Academy (GRAMMY)','अन्य_महत्त्वपूर्ण':'United Nations/UN calendar'}
questions=[]
for cat,items in categories.items():
    for i,(q,a,d) in enumerate(items,1):
        target=(i-1)%4
        opts=d[:]
        opts.insert(target,a)
        level='I' if i<=10 else 'II'
        types=['fact','fact','correct_option','statement_analysis'] if level=='I' else ['current_analysis','correct_option','comparison','source_analysis']
        typ=types[(i-1)%4]
        questions.append({'id':f'bo-1.8-{codes[cat]}-{i:02d}','unit':'1.8','category':cat,'level':level,'type':typ,'question':q,'options':opts,'correct':target,'solution':f'सही उत्तर: {chr(65+target)}। {a}।','source':sources[cat],'asOf':'2026-09-12'})
assert len(questions)==240
out=Path('exam-question-seed/branch-officer-1.8.json')
out.write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Generated',len(questions),'questions')
